#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# PROTOTYPE support for "Does Knock hold up against Cadence?" (#51).
# Sets up the Knock *Development* environment for the /prototype/knock spike.
# Run from the repo root:  bash scripts/knock-dev-setup.wizard.sh
# Needs KNOCK_SECRET_API_KEY, KNOCK_PUBLIC_API_KEY, KNOCK_FEED_CHANNEL_ID in .env.

KNOCK_API="https://api.knock.app/v1"
PROBE_USER="wizard-probe"

# Windows curl (schannel) can't check certificate revocation behind TLS inspection.
CURL=(curl -sS --max-time 20)
curl --version 2>/dev/null | grep -qi schannel && CURL+=(--ssl-no-revoke)

# knock_status METHOD PATH AUTH_KEY [BODY] prints the HTTP status code only.
knock_status() {
  local method="$1" path="$2" key="$3" body="${4:-}"
  local args=("${CURL[@]}" -o /dev/null -w '%{http_code}' -X "$method"
    -H "Authorization: Bearer $key" -H "Content-Type: application/json")
  [[ -n "$body" ]] && args+=(-d "$body")
  "${args[@]}" "$KNOCK_API$path" || printf '000'
}

# workflow_committed KEY: a trigger only works once the workflow is committed.
workflow_committed() {
  local code
  code=$(knock_status POST "/workflows/$1/trigger" "$SK" \
    "{\"recipients\":[{\"id\":\"$PROBE_USER\",\"name\":\"Wizard probe\"}]}")
  if [[ "$code" == 200 ]]; then
    printf '  %s✓ %s is committed and triggerable%s\n' "$GREEN" "$1" "$RESET"
  else
    warn "triggering $1 returned HTTP $code (404 = not found or not committed yet)"
    return 1
  fi
}

# verify_until "what" CMD...: re-run a check until it passes or the human skips it.
verify_until() {
  local what="$1"; shift
  say ""
  say "Checking $what against the Knock API…"
  until "$@"; do
    if confirm "Skip this check and move on?"; then
      SKIPPED+=("$what (check skipped, not verified)")
      return 0
    fi
    pause "Fix it in the dashboard, then press Enter to re-check"
  done
}

feed_requires_token() {
  local code
  code=$(knock_status GET "/users/$PROBE_USER/feeds/$FEED" "$PK")
  if [[ "$code" == 401 || "$code" == 403 ]]; then
    printf '  %s✓ feed without a user token → HTTP %s: enhanced security is ON%s\n' "$GREEN" "$code" "$RESET"
  else
    warn "feed without a user token → HTTP $code (expected 401): enhanced security looks OFF"
    return 1
  fi
}

workflow_stage() {
  local key="$1" body="$2"
  stage "Workflow: $key"
  open_url "https://dashboard.knock.app/~/workflows"
  note "Check the environment switcher says Development before you start."
  step "Create a new workflow. Name it anything, but set its key to exactly:  $key"
  step "Add a channel step for the In-app feed channel (the one Cadence's feed uses)."
  step "Open the step's template (\"Edit content\") and set:"
  say  "    Body (markdown):  $body"
  say  "    Action URL:       {{ data.url }}"
  step "Save, then Commit the workflow (its page, or https://dashboard.knock.app/~/commits → Commit all)."
  note "Knock's docs don't spell out every button here. If something's named differently, go by meaning."
  pause "Press Enter once $key is committed"
  verify_until "workflow $key" workflow_committed "$key"
  pause "Press Enter for the next stage"
}

run_wizard() {

TOTAL_STAGES=5

banner "Knock Development setup for the Knock spike"

stage "Keys and environment"
SK=$(_existing KNOCK_SECRET_API_KEY || true)
PK=$(_existing KNOCK_PUBLIC_API_KEY || true)
FEED=$(_existing KNOCK_FEED_CHANNEL_ID || true)
if [[ -z "$SK" || -z "$PK" || -z "$FEED" ]]; then
  warn "$ENV_FILE is missing KNOCK_SECRET_API_KEY, KNOCK_PUBLIC_API_KEY or KNOCK_FEED_CHANNEL_ID."
  say "Run this from the repo root that holds the Knock .env, then try again."
  exit 1
fi
say "Found the Development Knock keys in $ENV_FILE. Nothing new gets written there."
say "Everything below happens in Knock's ${BOLD}Development${RESET} environment, never Production."
open_url "https://dashboard.knock.app"
step "In the dashboard's environment switcher, pick Development."
code=$(knock_status GET "/users/$PROBE_USER" "$SK")
if [[ "$code" == 401 ]]; then
  warn "the secret key was rejected (HTTP 401). Fix .env before continuing."; exit 1
fi
printf '  %s✓ secret key accepted (HTTP %s)%s\n' "$GREEN" "$code" "$RESET"
pause "Press Enter once you're in Development"

workflow_stage "discussion-reply" \
  '**{{ actor.name }}** replied to your question in *{{ data.lesson_title }}*'

workflow_stage "new-enrollment" \
  '**{{ actor.name }}** enrolled in *{{ data.course_title }}*'

stage "Default preferences: new-enrollment off"
say "New Enrollment → Instructor must be off by default, so Instructors opt in."
open_url "https://dashboard.knock.app/~/preferences"
step "Platform → Preferences, still in Development."
step "Edit the environment default preference set so that:"
say  "    workflow new-enrollment → channel type In-app feed → OFF"
say  "  Leave everything else alone. As JSON that's:"
say  '    {"workflows": {"new-enrollment": {"channel_types": {"in_app_feed": false}}}}'
step "Save (and commit, if the dashboard asks)."
warn "If there's no way to set this in the dashboard, say so in the ticket. That counts against check 4."
note "There's no API check here. The spike's check 4 is what proves it."
if ! confirm "Is new-enrollment's in-app feed now off in the default preferences?"; then
  SKIPPED+=("Default preference: new-enrollment in_app_feed off")
fi

stage "Enhanced security mode: ON"
say "With it on, the browser can read a feed only with a server-signed user token."
say "That is check 1 of the spike."
open_url "https://dashboard.knock.app"
step "Platform → API keys, in Development."
step "Turn on enhanced security mode, the setting for client-side requests."
note "Cadence's .env already has KNOCK_SIGNING_KEY, so don't generate a new signing key."
pause "Press Enter once it's on"
verify_until "enhanced security mode" feed_requires_token

finish
say "Next: run the dev server in the spike worktree and open /prototype/knock."
note "The probe user \"$PROBE_USER\" got a couple of test messages. Ignore them."
}

run_wizard "$@"; exit
